<template><div class="container">  <div class="article-interaction">    <!-- 点赞按钮 -->    <div class="like-section">      <button         class="like-btn"         :class="{ liked: isLiked }"        @click="toggleLike"        :disabled="isLoading">        <i class="icon ion-ios-heart"></i>        <span>{{ likeCount }}</span>      </button>    </div>    <!-- 评论区 -->    <div class="comment-section">      <div class="comment-input">        <textarea           v-model="commentContent"          placeholder="写下你的评论..."          @keyup.enter="submitComment"          :disabled="!isLoggedIn">        </textarea>        <button           class="submit-btn"          @click="submitComment"          :disabled="!commentContent.trim() || !isLoggedIn">          提交评论        </button>      </div>      <div class="comment-list" v-if="comments.length > 0">        <h4>评论 ({{ comments.length }})</h4>        <div class="comment-item" v-for="comment in comments" :key="comment.id">          <div class="comment-header">            <span class="comment-user">{{ comment.username }}</span>            <span class="comment-time">{{ formatDate(comment.createTime) }}</span>            <button               class="delete-btn"              v-if="isCurrentUser(comment.username)"              @click="deleteComment(comment.id)"              :disabled="isLoading">              删除            </button>          </div>          <div class="comment-content">{{ comment.content }}</div>        </div>      </div>      <div class="no-comments" v-else>        <p>暂无评论，快来抢沙发吧！</p>      </div>    </div>  </div></div></template><script>import { formatDate } from '@/utils/formatDateUtils'import { likeArticle, unlikeArticle, checkLiked, getLikeCount, addComment, getComments, deleteComment } from '@/utils/api'export default {  name: 'ArticleInteraction',  props: {    articleId: {      type: Number,      required: true    }  },  data() {    return {      isLiked: false,      likeCount: 0,      commentContent: '',      comments: [],      isLoading: false,      isLoggedIn: false    }  },  created() {    this.isLoggedIn = this.$api.isLoggedIn()    this.loadData()  },  methods: {    async loadData() {      this.isLoading = true      try {        await Promise.all([          this.loadLikeStatus(),          this.loadComments()        ])      } catch (error) {        console.error('加载数据失败:', error)      } finally {        this.isLoading = false      }    },        async loadLikeStatus() {      if (this.isLoggedIn) {        const response = await checkLiked(this.articleId)        this.isLiked = response.data.data      }      const countResponse = await getLikeCount(this.articleId)      this.likeCount = countResponse.data.data    },        async loadComments() {      const response = await getComments(this.articleId)      this.comments = response.data.data || []    },        async toggleLike() {      if (!this.isLoggedIn) {        this.$Message.warning('请先登录')        return      }            this.isLoading = true      try {        if (this.isLiked) {          await unlikeArticle(this.articleId)          this.isLiked = false          this.likeCount--          this.$Message.success('已取消点赞')        } else {          await likeArticle(this.articleId)          this.isLiked = true          this.likeCount++          this.$Message.success('点赞成功')        }      } catch (error) {        this.$Message.error(error.message || '操作失败')      } finally {        this.isLoading = false      }    },        async submitComment() {      if (!this.isLoggedIn) {        this.$Message.warning('请先登录')        return      }            const content = this.commentContent.trim()      if (!content) {        this.$Message.warning('请输入评论内容')        return      }            this.isLoading = true      try {        await addComment({          articleId: this.articleId,          content: content,          username: this.$api.getUsername()        })        this.commentContent = ''        this.$Message.success('评论提交成功')        await this.loadComments()      } catch (error) {        this.$Message.error(error.message || '评论提交失败')      } finally {        this.isLoading = false      }    },        async deleteComment(commentId) {      if (!this.$api.isLoggedIn()) {        this.$Message.warning('请先登录')        return      }            this.isLoading = true      try {        await deleteComment(commentId)        this.$Message.success('评论删除成功')        await this.loadComments()      } catch (error) {        this.$Message.error(error.message || '评论删除失败')      } finally {        this.isLoading = false      }    },        isCurrentUser(username) {      return this.$api.getUsername() === username    },        formatDate(date) {      return formatDate(date)    }  }}</script><style scoped>.article-interaction {  margin-top: 20px;  padding: 20px;  background: #fff;  border-radius: 8px;  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);}.like-section {  margin-bottom: 20px;}.like-btn {  display: flex;  align-items: center;  gap: 8px;  padding: 10px 20px;  background: #f5f7fa;  border: 1px solid #e4e7ed;  border-radius: 20px;  cursor: pointer;  font-size: 14px;  color: #606266;  transition: all 0.3s;}.like-btn:hover {  background: #ecf5ff;  border-color: #c6e2ff;  color: #409eff;}.like-btn.liked {  background: #fef0f0;  border-color: #fbc4c4;  color: #f56c6c;}.like-btn.liked .icon {  animation: likeAnimation 0.5s ease-in-out;}@keyframes likeAnimation {  0%, 100% {    transform: scale(1);  }  50% {    transform: scale(1.3);  }}.comment-section {  border-top: 1px solid #e4e7ed;  padding-top: 20px;}.comment-input {  margin-bottom: 20px;}.comment-input textarea {  width: 100%;  min-height: 80px;  padding: 10px;  border: 1px solid #e4e7ed;  border-radius: 4px;  font-size: 14px;  resize: vertical;  margin-bottom: 10px;}.comment-input textarea:disabled {  background: #f5f7fa;  cursor: not-allowed;}.submit-btn {  float: right;  padding: 8px 16px;  background: #409eff;  border: none;  border-radius: 4px;  color: #fff;  cursor: pointer;  font-size: 14px;  transition: background 0.3s;}.submit-btn:hover:not(:disabled) {  background: #66b1ff;}.submit-btn:disabled {  background: #c0c4cc;  cursor: not-allowed;}.comment-list h4 {  margin-bottom: 15px;  font-size: 16px;  color: #303133;}.comment-item {  padding: 15px 0;  border-bottom: 1px solid #f0f2f5;}.comment-item:last-child {  border-bottom: none;}.comment-header {  display: flex;  justify-content: space-between;  align-items: center;  margin-bottom: 8px;  font-size: 12px;}.comment-user {  font-weight: bold;  color: #303133;}.comment-time {  color: #909399;}.delete-btn {  padding: 2px 8px;  background: #fef0f0;  border: 1px solid #fbc4c4;  border-radius: 4px;  color: #f56c6c;  cursor: pointer;  font-size: 12px;  transition: all 0.3s;}.delete-btn:hover:not(:disabled) {  background: #fde2e2;  border-color: #f9c2c2;}.delete-btn:disabled {  background: #f5f7fa;  border-color: #e4e7ed;  color: #c0c4cc;  cursor: not-allowed;}.comment-content {  font-size: 14px;  color: #606266;  line-height: 1.6;}.no-comments {  text-align: center;  padding: 40px 0;  color: #909399;  font-size: 14px;}.clearfix::after {  content: '';  display: table;  clear: both;}</style>